package local.mediacentre.client.ui;
import android.app.Activity;
import android.widget.*;
import local.mediacentre.client.R;
public final class StyleProbe {
    private static android.view.View find(android.view.View v,String id){if(id.equals(v.getContentDescription()))return v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int n=0;n<g.getChildCount();n++){android.view.View hit=find(g.getChildAt(n),id);if(hit!=null)return hit;}}return null;}
    private static void apply(Activity a)throws Exception{java.lang.reflect.Method m=MainActivity.class.getDeclaredMethod("applyDisplay");m.setAccessible(true);m.invoke(a);}
    private static void geometry(android.view.View v,StringBuilder out){out.append(v.getClass().getName()).append('/').append(v.getId()).append('/').append(v.getVisibility()).append(':').append(v.getLeft()).append(',').append(v.getTop()).append(',').append(v.getWidth()).append(',').append(v.getHeight()).append(';');if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int n=0;n<g.getChildCount();n++)geometry(g.getChildAt(n),out);}}
    private static String geometryDifference(String before,String after){String[] a=before.split(";"),b=after.split(";");StringBuilder result=new StringBuilder();for(int n=0;n<Math.min(a.length,b.length);n++)if(!a[n].equals(b[n]))result.append(n).append(" [").append(a[n]).append("] -> [").append(b[n]).append("] ");return result.toString();}
    public static void theme(Activity a,String action)throws Exception{
        android.content.SharedPreferences p=DisplaySettings.preferences(a);
        if("preview".equals(action)){EditText address=(EditText)find(a.findViewById(R.id.panel_root),"pair_address");if(address!=null)address.setText("https://panel.example:8445");((TextView)a.findViewById(R.id.status)).setText("ТЕСТОВЫЕ ДАННЫЕ · демонстрационные настройки");return;}
        if(!"verify".equals(action)){if(!"light".equals(action)&&!"dark".equals(action)&&!"auto".equals(action))throw new IllegalArgumentException();p.edit().putString("theme",action).commit();apply(a);android.util.Log.i("MediaCentreH7","H7_THEME_SET "+action);return;}
        final android.view.View root=a.findViewById(R.id.panel_root);final EditText edit=(EditText)find(root,"pair_address");if(edit==null)throw new IllegalStateException("Open settings first");
        final String original=edit.getText().toString(),mode=p.getString("theme",null);final int start=p.getInt("night_start",22),end=p.getInt("night_end",7);final boolean hadStart=p.contains("night_start"),hadEnd=p.contains("night_end"),hadNight=p.contains("night"),night=p.getBoolean("night",false);
        final int players=local.mediacentre.client.radio.RadioPlaybackService.players(),position=local.mediacentre.client.radio.RadioPlaybackService.position();
        edit.setText("unsaved-theme-test");edit.requestFocus();edit.setSelection(3,8);final ScrollView scroll=a.findViewById(R.id.content_scroll);scroll.scrollTo(0,80);
        p.edit().putBoolean("night",false).commit();apply(a);final float brightness=a.getWindow().getAttributes().screenBrightness;
        root.postDelayed(new Runnable(){int step=0;String baseline;int scrollY;public void run(){try{
            if(step==0){StringBuilder b=new StringBuilder();geometry(root,b);baseline=b.toString();scrollY=scroll.getScrollY();}
            else{StringBuilder b=new StringBuilder();geometry(root,b);if(!baseline.equals(b.toString())||root!=a.findViewById(R.id.panel_root)||!edit.hasFocus()||!"unsaved-theme-test".equals(edit.getText().toString())||edit.getSelectionStart()!=3||edit.getSelectionEnd()!=8||scrollY!=scroll.getScrollY()||brightness!=a.getWindow().getAttributes().screenBrightness||players!=local.mediacentre.client.radio.RadioPlaybackService.players()||local.mediacentre.client.radio.RadioPlaybackService.position()<position)throw new IllegalStateException("Theme changed: step="+step+" geometry="+baseline.equals(b.toString())+" difference="+geometryDifference(baseline,b.toString())+" root="+(root==a.findViewById(R.id.panel_root))+" focus="+edit.hasFocus()+" input="+"unsaved-theme-test".equals(edit.getText().toString())+" selection="+edit.getSelectionStart()+":"+edit.getSelectionEnd()+" scroll="+scrollY+":"+scroll.getScrollY()+" brightness="+brightness+":"+a.getWindow().getAttributes().screenBrightness+" players="+players+":"+local.mediacentre.client.radio.RadioPlaybackService.players()+" position="+position+":"+local.mediacentre.client.radio.RadioPlaybackService.position());}
            if(step==4){restore();android.util.Log.i("MediaCentreH7","H7_THEME_VERIFY_OK same_views_geometry_input_focus_scroll_player brightness_independent");return;}
            java.util.Calendar now=java.util.Calendar.getInstance(java.util.TimeZone.getTimeZone(p.getString("timezone","Europe/Moscow")));int hour=now.get(java.util.Calendar.HOUR_OF_DAY);
            String target=step==0?"dark":step==1?"light":"auto";p.edit().putString("theme",target).putInt("night_start",step==2?hour:(hour+1)%24).putInt("night_end",step==2?(hour+1)%24:hour).commit();apply(a);boolean expected=step==0||step==2;if(new PanelStyle(a).palette.dark!=expected)throw new IllegalStateException("Wrong scheduled palette");step++;root.postDelayed(this,200);
        }catch(Exception e){restore();android.util.Log.e("MediaCentreH7","H7_THEME_VERIFY_ERROR",e);}}
        private void restore(){android.content.SharedPreferences.Editor e=p.edit();if(mode==null)e.remove("theme");else e.putString("theme",mode);if(hadStart)e.putInt("night_start",start);else e.remove("night_start");if(hadEnd)e.putInt("night_end",end);else e.remove("night_end");if(hadNight)e.putBoolean("night",night);else e.remove("night");e.commit();edit.setText(original);try{apply(a);}catch(Exception ignored){}}},200);
    }
    public static void render(Activity a){PanelStyle s=new PanelStyle(a);LinearLayout root=a.findViewById(R.id.content);root.removeAllViews();root.addView(s.title("Северный свет · компоненты",32));root.addView(s.text("Кириллица · Санкт-Петербург · −12° · 92,5075 руб.",22,PanelStyle.TEXT));root.addView(s.text("Вторичная подпись · источник и дата",18,PanelStyle.MUTED));root.addView(s.text("Нет связи · сохранённые данные",18,PanelStyle.WARNING));LinearLayout row=new LinearLayout(a);root.addView(row);for(String label:new String[]{"Слушать","Обычная","Недоступна","Фокус"}){Button b=s.button(label,"component_"+label,()->{});if(label.equals("Слушать"))s.buttonStyle(b,true);if(label.equals("Недоступна"))b.setEnabled(false);if(label.equals("Фокус")){b.setFocusableInTouchMode(true);b.requestFocus();}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,s.dp(56),1);p.rightMargin=s.dp(12);row.addView(b,p);}for(int n:new int[]{0,50,100}){SeekBar bar=s.slider();bar.setProgress(n);root.addView(bar,new LinearLayout.LayoutParams(-1,s.dp(52)));}CheckBox c=new CheckBox(a);c.setText("Выбранная настройка");s.checkbox(c);c.setChecked(true);root.addView(c);EditText edit=new EditText(a);s.input(edit);edit.setHint("Поиск станции");root.addView(edit);}
}
